/*
 * Baloot: rules, scoring and AI, ported from the Python package in this repo.
 *
 * The same four techniques as the desktop version: legal moves and hidden-hand
 * sampling as a CSP, a knowledge base of proven facts, alpha-beta search, and
 * Perfect Information Monte Carlo on top. Doubling decisions use Monte Carlo
 * rollouts.
 *
 * Cards are short strings: "JH", "10S", "AD" (rank + suit letter).
 * A table is an array of [playerId, card] in play order. Seats 0..3 play in
 * that order; teams are {0,2} and {1,3}.
 *
 * tests/web/core.test.js checks this file against fixtures generated by the
 * Python engine, so both implementations must stay in step.
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.Baloot = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  // ---------------------------------------------------------------- cards
  const SUITS = ["S", "H", "D", "C"];
  const SUIT_NAMES = { S: "Spades", H: "Hearts", D: "Diamonds", C: "Clubs" };
  const SUIT_SYMBOLS = { S: "\u2660", H: "\u2665", D: "\u2666", C: "\u2663" };
  const RED_SUITS = { H: true, D: true };
  const RANKS = ["7", "8", "9", "10", "J", "Q", "K", "A"];
  const TRUMP_ORDER = ["7", "8", "Q", "K", "10", "A", "9", "J"];
  const PLAIN_ORDER = ["7", "8", "9", "J", "Q", "K", "10", "A"];
  const PLAIN_POINTS = { A: 11, "10": 10, K: 4, Q: 3, J: 2, "9": 0, "8": 0, "7": 0 };
  const TRUMP_POINTS = { J: 20, "9": 14, A: 11, "10": 10, K: 4, Q: 3, "8": 0, "7": 0 };
  const LAST_TRICK_BONUS = 10;
  const HOKOM = "Hokom", SUN = "Sun";

  const rankOf = (c) => (c.length === 3 ? "10" : c[0]);
  const suitOf = (c) => c[c.length - 1];
  const isRed = (c) => !!RED_SUITS[suitOf(c)];
  const makeCard = (rank, suit) => rank + suit;

  function fullDeck() {
    const deck = [];
    for (const s of SUITS) for (const r of RANKS) deck.push(makeCard(r, s));
    return deck;
  }

  function shuffled(deck, rng) {
    const out = deck.slice();
    for (let i = out.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
  }

  /** Deterministic RNG so games can be replayed from a seed. */
  function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
      a = (a + 0x6d2b79f5) >>> 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const choice = (arr, rng) => arr[Math.floor(rng() * arr.length)];

  function sortHand(hand, trump) {
    const order = SUITS.slice();
    if (trump && order.includes(trump)) {
      order.splice(order.indexOf(trump), 1);
      order.unshift(trump);
    }
    return hand.slice().sort((a, b) =>
      order.indexOf(suitOf(a)) - order.indexOf(suitOf(b)) ||
      RANKS.indexOf(rankOf(a)) - RANKS.indexOf(rankOf(b)));
  }

  // ---------------------------------------------------------------- rules
  const teamOf = (pid) => pid % 2;
  const partnerOf = (pid) => (pid + 2) % 4;
  const isTrump = (card, mode, trump) => mode === HOKOM && suitOf(card) === trump;
  const trumpStrength = (card) => TRUMP_ORDER.indexOf(rankOf(card));
  const plainStrength = (card) => PLAIN_ORDER.indexOf(rankOf(card));

  function cardPoints(card, mode, trump) {
    return isTrump(card, mode, trump) ? TRUMP_POINTS[rankOf(card)] : PLAIN_POINTS[rankOf(card)];
  }

  function trickPoints(table, mode, trump) {
    return table.reduce((sum, [, c]) => sum + cardPoints(c, mode, trump), 0);
  }

  function beats(challenger, current, mode, trump) {
    if (mode === HOKOM) {
      const ct = suitOf(challenger) === trump, wt = suitOf(current) === trump;
      if (ct && !wt) return true;
      if (wt && !ct) return false;
      if (ct && wt) return trumpStrength(challenger) > trumpStrength(current);
    }
    return suitOf(challenger) === suitOf(current) && plainStrength(challenger) > plainStrength(current);
  }

  function trickWinner(table, mode, trump) {
    if (!table.length) throw new Error("Empty table has no winner");
    let [winPid, winCard] = table[0];
    for (const [pid, card] of table.slice(1)) {
      if (beats(card, winCard, mode, trump)) { winPid = pid; winCard = card; }
    }
    return winPid;
  }

  function highestTrumpOnTable(table, trump) {
    const trumps = table.filter(([, c]) => suitOf(c) === trump).map(([, c]) => c);
    if (!trumps.length) return null;
    return trumps.reduce((best, c) => (trumpStrength(c) > trumpStrength(best) ? c : best));
  }

  /** The play constraints (a CSP filter over the hand). */
  function legalMoves(hand, table, mode, trump, locked) {
    if (!table.length) {
      if (locked && mode === HOKOM) {
        const nonTrumps = hand.filter((c) => suitOf(c) !== trump);
        if (nonTrumps.length) return nonTrumps;           // closed: no trump leads
      }
      return hand.slice();
    }
    const lead = suitOf(table[0][1]);
    const follow = hand.filter((c) => suitOf(c) === lead);
    if (follow.length) {
      if (mode === HOKOM && lead === trump) {
        const top = highestTrumpOnTable(table, trump);
        const higher = follow.filter((c) => trumpStrength(c) > trumpStrength(top));
        if (higher.length) return higher;
      }
      return follow;
    }
    if (mode === HOKOM) {
      const me = (table[0][0] + table.length) % 4;
      if (trickWinner(table, mode, trump) === partnerOf(me)) return hand.slice();
      const trumps = hand.filter((c) => suitOf(c) === trump);
      if (trumps.length) {
        const top = highestTrumpOnTable(table, trump);
        if (top !== null) {
          const higher = trumps.filter((c) => trumpStrength(c) > trumpStrength(top));
          if (higher.length) return higher;
        }
        return trumps;
      }
    }
    return hand.slice();
  }

  // ------------------------------------------------------------- projects
  const RAW_SIRA = 20, RAW_FIFTY = 50, RAW_HUNDRED = 100, RAW_FOUR_HUNDRED = 400, RAW_BALOOT = 20;

  const projectPoints = (raw, mode) => (mode === HOKOM ? Math.floor(raw / 10) : Math.floor(raw / 5));

  function runsIn(suitCards) {
    const ordered = suitCards.slice().sort((a, b) => RANKS.indexOf(rankOf(a)) - RANKS.indexOf(rankOf(b)));
    const runs = [];
    let current = [];
    for (const card of ordered) {
      if (current.length && RANKS.indexOf(rankOf(card)) === RANKS.indexOf(rankOf(current[current.length - 1])) + 1) {
        current.push(card);
      } else {
        if (current.length >= 3) runs.push(current);
        current = [card];
      }
    }
    if (current.length >= 3) runs.push(current);
    return runs;
  }

  function detectProjects(hand, mode, trump) {
    const projects = [];
    for (const suit of SUITS) {
      for (const run of runsIn(hand.filter((c) => suitOf(c) === suit))) {
        const top = RANKS.indexOf(rankOf(run[run.length - 1]));
        if (run.length === 3) projects.push({ name: "Sira", cards: run, raw: RAW_SIRA, topRank: top });
        else if (run.length === 4) projects.push({ name: "50", cards: run, raw: RAW_FIFTY, topRank: top });
        else projects.push({ name: "100", cards: run, raw: RAW_HUNDRED, topRank: top });
      }
    }
    for (const rank of ["10", "J", "Q", "K", "A"]) {
      const same = hand.filter((c) => rankOf(c) === rank);
      if (same.length === 4) {
        const top = RANKS.indexOf(rank);
        if (rank === "A" && mode === SUN) projects.push({ name: "400", cards: same, raw: RAW_FOUR_HUNDRED, topRank: top });
        else projects.push({ name: "100", cards: same, raw: RAW_HUNDRED, topRank: top });
      }
    }
    if (mode === HOKOM && trump) {
      const kq = hand.filter((c) => suitOf(c) === trump && (rankOf(c) === "K" || rankOf(c) === "Q"));
      if (kq.length === 2) projects.push({ name: "Baloot", cards: kq, raw: RAW_BALOOT, topRank: RANKS.indexOf("K") });
    }
    return projects;
  }

  /** Only the team with the best project scores; Baloot always scores. */
  function resolveDeclarations(projectsByPid, mode) {
    const best = [[-1, -1], [-1, -1]];
    for (const pid of [0, 1, 2, 3]) {
      for (const p of projectsByPid[pid] || []) {
        if (p.name === "Baloot") continue;
        const t = teamOf(pid);
        if (p.raw > best[t][0] || (p.raw === best[t][0] && p.topRank > best[t][1])) best[t] = [p.raw, p.topRank];
      }
    }
    const cmp = best[0][0] - best[1][0] || best[0][1] - best[1][1];
    const winningTeam = cmp > 0 ? 0 : cmp < 0 ? 1 : null;
    const result = {
      winningTeam, teamPoints: [0, 0], projectPoints: [0, 0], balootPoints: [0, 0], shown: {},
    };
    for (const pid of [0, 1, 2, 3]) {
      const t = teamOf(pid);
      for (const p of projectsByPid[pid] || []) {
        const value = projectPoints(p.raw, mode);
        if (p.name === "Baloot") {
          result.teamPoints[t] += value;
          result.balootPoints[t] += value;
        } else if (winningTeam === t) {
          result.teamPoints[t] += value;
          result.projectPoints[t] += value;
          (result.shown[pid] = result.shown[pid] || []).push(p);
        }
      }
    }
    return result;
  }

  // -------------------------------------------------------------- scoring
  const NORMAL = 1, DOUBLE = 2, THREE = 3, FOUR = 4, QAHWA = 5;
  const LEVEL_NAMES = { 1: "", 2: "Double", 3: "Three", 4: "Four", 5: "Qahwa" };
  const LEVEL_NAMES_AR = { 1: "", 2: "\u062f\u0628\u0644", 3: "\u062b\u0631\u064a", 4: "\u0641\u0648\u0631", 5: "\u0642\u0647\u0648\u0629" };

  const baseTotal = (mode) => (mode === HOKOM ? 16 : 26);
  const roundingUnit = (mode) => (mode === HOKOM ? 10 : 5);

  /** Hokom: trailing 5 rounds down. Sun: a trailing 5 is not rounded. */
  function convertCountingPoints(raw, mode) {
    if (mode === HOKOM) return Math.floor((raw + 4) / 10);
    if (raw % 10 === 5) return Math.floor(raw / 5);
    return 2 * Math.floor((raw + 5) / 10);
  }

  const raisingTeam = (declarerTeam, level) =>
    (level === DOUBLE || level === FOUR ? 1 - declarerTeam : declarerTeam);
  const countingTeam = (declarerTeam, level) => 1 - raisingTeam(declarerTeam, level);

  function scoreHand(mode, declarerTeam, cardPointsPerTeam, projects, baloots, level) {
    projects = projects || [0, 0];
    baloots = baloots || [0, 0];
    level = level || NORMAL;
    const totalGp = baseTotal(mode), unit = roundingUnit(mode);
    const c = countingTeam(declarerTeam, level);
    const gp = [0, 0];
    gp[c] = convertCountingPoints(cardPointsPerTeam[c], mode);
    gp[1 - c] = totalGp - gp[c];
    const totals = [0, 1].map((t) => gp[t] + projects[t] + baloots[t]);

    let winner;
    if (totals[0] !== totals[1]) winner = totals[0] > totals[1] ? 0 : 1;
    else {
      const lost = [0, 1].map((t) => cardPointsPerTeam[t] - unit * gp[t]);
      if (lost[0] !== lost[1]) winner = lost[0] > lost[1] ? 0 : 1;
      else winner = declarerTeam;                    // art. 7-6: a tie loses for the doubler
    }

    const projectTotal = projects[0] + projects[1];
    const balootTotal = baloots[0] + baloots[1];
    const final = [0, 0];
    if (level === NORMAL) {
      if (winner === declarerTeam) { final[0] = totals[0]; final[1] = totals[1]; }
      else final[winner] = totalGp + projectTotal + balootTotal;
    } else {
      const mult = Math.min(level, FOUR);
      final[winner] = totalGp * mult + projectTotal * Math.min(mult, 2) + balootTotal;
    }
    return {
      gamePoints: gp, totals, countingTeam: c, winner,
      declarerWon: winner === declarerTeam, final, qahwa: level === QAHWA,
    };
  }

  // ------------------------------------------------------- knowledge base
  class KnowledgeBase {
    constructor(myId) { this.myId = myId; this.reset(); }

    reset() {
      this.played = new Set();
      this.playedBy = [0, 0, 0, 0];
      this.voids = [new Set(), new Set(), new Set(), new Set()];
      this.known = [new Set(), new Set(), new Set(), new Set()];
      this.excluded = [new Set(), new Set(), new Set(), new Set()];
      this.log = [];
      this.locked = false;
    }

    observeContract(mode, trump, locked, taker, groundCard) {
      this.locked = !!locked && mode === HOKOM;
      if (taker !== this.myId && !this.played.has(groundCard) && !this.known[taker].has(groundCard)) {
        this.known[taker].add(groundCard);                                    // R6
        this.log.push(`R6: P${taker} holds ${groundCard} (ground card)`);
      }
    }

    observePlay(pid, card, tableBefore, mode, trump) {
      if (tableBefore.length) this._inferFromPlay(pid, card, tableBefore, mode, trump);
      else if (this.locked && mode === HOKOM && suitOf(card) === trump) {
        for (const suit of SUITS) if (suit !== trump) this._addVoid(pid, suit, "R7");
      }
      this.played.add(card);                                                  // R5
      this.playedBy[pid] += 1;
      for (let p = 0; p < 4; p++) this.known[p].delete(card);
    }

    observeDeclaration(pid, cards) {
      const newly = cards.filter((c) => !this.played.has(c) && !this.known[pid].has(c));
      newly.forEach((c) => this.known[pid].add(c));                            // R4
      if (newly.length) this.log.push(`R4: P${pid} holds ${newly.join(" ")} (declared)`);
    }

    _inferFromPlay(pid, card, tableBefore, mode, trump) {
      const lead = suitOf(tableBefore[0][1]);
      if (suitOf(card) !== lead) {
        this._addVoid(pid, lead, "R1");
        if (mode !== HOKOM || lead === trump) return;
        if (trickWinner(tableBefore, mode, trump) === partnerOf(pid)) return;
        if (suitOf(card) !== trump) this._addVoid(pid, trump, "R2");
        else this._excludeHigherTrumps(pid, card, tableBefore, trump);
        return;
      }
      if (mode === HOKOM && lead === trump) this._excludeHigherTrumps(pid, card, tableBefore, trump);
    }

    _excludeHigherTrumps(pid, card, tableBefore, trump) {
      const top = highestTrumpOnTable(tableBefore, trump);
      if (top === null || trumpStrength(card) > trumpStrength(top)) return;
      const newly = [];
      for (const rank of TRUMP_ORDER.slice(trumpStrength(top) + 1)) {
        const c = makeCard(rank, trump);
        if (!this.played.has(c) && !this.excluded[pid].has(c)) { this.excluded[pid].add(c); newly.push(c); }
      }
      if (newly.length) this.log.push(`R3: P${pid} holds none of ${newly.join(" ")}`);
    }

    _addVoid(pid, suit, rule) {
      if (!this.voids[pid].has(suit)) {
        this.voids[pid].add(suit);
        this.log.push(`${rule}: P${pid} is void in ${SUIT_NAMES[suit]}`);
      }
    }

    cardsInHand(pid) { return 8 - this.playedBy[pid]; }

    canHold(pid, card) {
      return !this.played.has(card) && !this.voids[pid].has(suitOf(card)) && !this.excluded[pid].has(card);
    }

    snapshot() {
      const kb = new KnowledgeBase(this.myId);
      kb.played = new Set(this.played);
      kb.playedBy = this.playedBy.slice();
      kb.voids = this.voids.map((s) => new Set(s));
      kb.known = this.known.map((s) => new Set(s));
      kb.excluded = this.excluded.map((s) => new Set(s));
      kb.locked = this.locked;
      return kb;
    }

    consistentWith(hands) {
      for (let pid = 0; pid < 4; pid++) {
        const hand = hands[pid];
        if (!hand) continue;
        if (hand.length !== this.cardsInHand(pid)) return false;
        for (const c of this.known[pid]) if (!hand.includes(c)) return false;
        for (const c of hand) if (!this.canHold(pid, c)) return false;
      }
      return true;
    }
  }

  // --------------------------------------------------------- deal sampler
  class DealSampler {
    constructor(kb, myHand, rng, nodeLimit) {
      this.kb = kb;
      this.me = kb.myId;
      this.myHand = myHand.slice();
      this.rng = rng;
      this.nodeLimit = nodeLimit || 5000;
      this.others = [0, 1, 2, 3].filter((p) => p !== this.me);
      const hidden = new Set([...this.myHand, ...kb.played]);
      for (const p of this.others) for (const c of kb.known[p]) hidden.add(c);
      this.unknown = fullDeck().filter((c) => !hidden.has(c));
    }

    sample() {
      let deal = this._solve(true);
      if (!deal) deal = this._solve(false);
      if (!deal) deal = this._fillBySizeOnly();
      if (deal) deal[this.me] = this.myHand.slice();
      return deal;
    }

    _solve(useExclusions) {
      const kb = this.kb;
      const hands = {}, capacity = {};
      for (const p of this.others) {
        hands[p] = [...kb.known[p]];
        capacity[p] = kb.cardsInHand(p) - hands[p].length;
        if (capacity[p] < 0) return null;
      }
      if (this.others.reduce((s, p) => s + capacity[p], 0) !== this.unknown.length) return null;

      const allowed = (p, c) =>
        !kb.voids[p].has(suitOf(c)) && !(useExclusions && kb.excluded[p].has(c));
      const domains = new Map(this.unknown.map((c) => [c, this.others.filter((p) => allowed(p, c))]));
      const unassigned = shuffled(this.unknown, this.rng);
      let nodes = 0;

      const forwardCheck = () => {
        for (const p of this.others) {
          if (capacity[p] > 0) {
            let available = 0;
            for (const c of unassigned) if (domains.get(c).includes(p)) available++;
            if (available < capacity[p]) return false;
          }
        }
        return unassigned.every((c) => domains.get(c).some((p) => capacity[p] > 0));
      };

      const backtrack = () => {
        if (!unassigned.length) return true;
        if (++nodes > this.nodeLimit) return false;
        // MRV: the card with the fewest players that can still take it.
        let card = unassigned[0], bestCount = Infinity;
        for (const c of unassigned) {
          const count = domains.get(c).filter((p) => capacity[p] > 0).length;
          if (count < bestCount) { bestCount = count; card = c; }
        }
        const options = shuffled(domains.get(card).filter((p) => capacity[p] > 0), this.rng);
        unassigned.splice(unassigned.indexOf(card), 1);
        for (const p of options) {
          hands[p].push(card);
          capacity[p] -= 1;
          if (forwardCheck() && backtrack()) return true;
          capacity[p] += 1;
          hands[p].pop();
        }
        unassigned.push(card);
        return false;
      };

      if (!forwardCheck() || !backtrack()) return null;
      return hands;
    }

    _fillBySizeOnly() {
      let pool = shuffled(this.unknown, this.rng);
      const hands = {};
      for (const p of this.others) {
        hands[p] = [...this.kb.known[p]];
        const need = this.kb.cardsInHand(p) - hands[p].length;
        if (need < 0) return null;
        hands[p] = hands[p].concat(pool.slice(0, need));
        pool = pool.slice(need);
      }
      return hands;
    }
  }

  // ---------------------------------------------------------------- search
  const HORIZON = 2, HORIZON_FULL = 4;

  class TrickSearch {
    constructor(me, mode, trump, horizonTricks, locked) {
      this.me = me; this.mode = mode; this.trump = trump;
      this.horizon = Math.max(1, horizonTricks);
      this.locked = !!locked;
      this.nodes = 0;
    }

    moveValues(hands, table, moves) {
      const copy = {};
      for (const p of [0, 1, 2, 3]) copy[p] = hands[p].slice();
      const work = table.slice();
      const toPlay = work.length ? (work[0][0] + work.length) % 4 : this.me;
      const values = new Map();
      for (const move of moves) {
        copy[toPlay].splice(copy[toPlay].indexOf(move), 1);
        work.push([toPlay, move]);
        values.set(move, this._ab(copy, work, (toPlay + 1) % 4, this.horizon, -Infinity, Infinity));
        work.pop();
        copy[toPlay].push(move);
      }
      return values;
    }

    _ab(hands, table, toPlay, tricksLeft, alpha, beta) {
      this.nodes++;
      if (table.length === 4) {
        const winner = trickWinner(table, this.mode, this.trump);
        let pts = trickPoints(table, this.mode, this.trump);
        const last = [0, 1, 2, 3].every((p) => hands[p].length === 0);
        if (last) pts += LAST_TRICK_BONUS;
        const gain = winner % 2 === this.me % 2 ? pts : -pts;
        if (last || tricksLeft <= 1) return gain;
        return gain + this._ab(hands, [], winner, tricksLeft - 1, alpha - gain, beta - gain);
      }
      const hand = hands[toPlay];
      const moves = legalMoves(hand, table, this.mode, this.trump, this.locked);
      if (!moves.length) return 0;
      moves.sort((a, b) => this._orderKey(b) - this._orderKey(a));

      const maximizing = toPlay % 2 === this.me % 2;
      let best = maximizing ? -Infinity : Infinity;
      for (const move of moves) {
        hand.splice(hand.indexOf(move), 1);
        table.push([toPlay, move]);
        const value = this._ab(hands, table, (toPlay + 1) % 4, tricksLeft, alpha, beta);
        table.pop();
        hand.push(move);
        if (maximizing) { best = Math.max(best, value); alpha = Math.max(alpha, value); }
        else { best = Math.min(best, value); beta = Math.min(beta, value); }
        if (beta <= alpha) break;
      }
      return best;
    }

    _orderKey(card) {
      if (isTrump(card, this.mode, this.trump)) return 100 + trumpStrength(card);
      return (cardPoints(card, this.mode, this.trump) >= 10 ? 50 : 0) + plainStrength(card);
    }
  }

  // -------------------------------------------------------------- policies
  function cheapness(card, mode, trump) {
    const strength = isTrump(card, mode, trump) ? trumpStrength(card) : plainStrength(card);
    return (isTrump(card, mode, trump) ? 10000 : 0) + cardPoints(card, mode, trump) * 100 + strength;
  }

  function greedyCard(pid, hand, table, mode, trump, locked) {
    const legal = legalMoves(hand, table, mode, trump, locked);
    const cheapest = (cards) => cards.reduce((a, b) => (cheapness(b, mode, trump) < cheapness(a, mode, trump) ? b : a));
    if (!table.length) {
      return legal.reduce((best, c) => {
        const key = (x) => (isTrump(x, mode, trump) ? -1 : plainStrength(x)) * 100 + cardPoints(x, mode, trump);
        return key(c) > key(best) ? c : best;
      });
    }
    const winnerPid = trickWinner(table, mode, trump);
    if (winnerPid % 2 === pid % 2) return cheapest(legal);
    const current = table.find(([p]) => p === winnerPid)[1];
    const winners = legal.filter((c) => beats(c, current, mode, trump));
    return cheapest(winners.length ? winners : legal);
  }

  // --------------------------------------------------------------- bidding
  const PASS = "Pass", BUY_SUN = "Sun", BUY_HOKOM = "Hokom",
        BUY_HOKOM_THANI = "Hokom thani", BUY_ASHKAL = "Ashkal";
  const HOKOM_THRESHOLD = 7.0, SUN_THRESHOLD = 7.0, ASHKAL_MAX_GAIN = 0.5;

  function hokomStrength(cards, trump) {
    const weights = { J: 3.5, "9": 2.5, A: 1.5, "10": 1.0 };
    let score = 0;
    for (const c of cards) {
      if (suitOf(c) === trump) score += weights[rankOf(c)] !== undefined ? weights[rankOf(c)] : 0.5;
      else if (rankOf(c) === "A") score += 1.0;
      else if (rankOf(c) === "10" && cards.includes(makeCard("A", suitOf(c)))) score += 0.5;
    }
    return score;
  }

  function sunStrength(cards) {
    let score = 0;
    for (const c of cards) {
      if (rankOf(c) === "A") score += 2.5;
      else if (rankOf(c) === "10") score += cards.includes(makeCard("A", suitOf(c))) ? 1.0 : 0.5;
      else if (rankOf(c) === "K") score += 0.3;
    }
    return score;
  }

  function bestThaniSuit(hand, groundCard) {
    const withCard = hand.concat([groundCard]);
    return SUITS.filter((s) => s !== suitOf(groundCard))
      .reduce((best, s) => (hokomStrength(withCard, s) > hokomStrength(withCard, best) ? s : best));
  }

  function sunOrAshkal(hand, groundCard, options) {
    if (options.includes(BUY_ASHKAL)) {
      const gain = sunStrength(hand.concat([groundCard])) - sunStrength(hand);
      if (gain < ASHKAL_MAX_GAIN) return [BUY_ASHKAL, null];
    }
    return [BUY_SUN, null];
  }

  /** The Mushtra heuristic: the Python fallback when no model file is present. */
  function decideBid(hand, groundCard, bidRound, options) {
    const withCard = hand.concat([groundCard]);
    let choiceMade = [PASS, null];
    if (sunStrength(withCard) >= SUN_THRESHOLD) choiceMade = sunOrAshkal(hand, groundCard, options);
    else if (bidRound === 1) {
      if (options.includes(BUY_HOKOM) && hokomStrength(withCard, suitOf(groundCard)) >= HOKOM_THRESHOLD)
        choiceMade = [BUY_HOKOM, suitOf(groundCard)];
    } else if (options.includes(BUY_HOKOM_THANI)) {
      const suit = bestThaniSuit(hand, groundCard);
      if (hokomStrength(withCard, suit) >= HOKOM_THRESHOLD) choiceMade = [BUY_HOKOM_THANI, suit];
    }
    return options.includes(choiceMade[0]) ? choiceMade : [PASS, null];
  }

  // ------------------------------------------------------------ escalation
  const CALL_DOUBLE = "Double", CALL_DOUBLE_CLOSED = "Double closed", CALL_THREE = "Three",
        CALL_FOUR = "Four", CALL_FOUR_CLOSED = "Four closed", CALL_QAHWA = "Qahwa";
  const CALL_EFFECT = {
    [CALL_DOUBLE]: [DOUBLE, false],
    [CALL_DOUBLE_CLOSED]: [DOUBLE, true],
    [CALL_THREE]: [THREE, false],
    [CALL_FOUR]: [FOUR, false],
    [CALL_FOUR_CLOSED]: [FOUR, true],
    [CALL_QAHWA]: [QAHWA, false],
  };
  const SUN_DOUBLE_LIMIT = 100;
  const DOUBLER_MODEL_STRENGTH = 4.0;

  /** Art. 7-2: defenders at 100 or fewer, buyers above 100. */
  const sunDoubleAllowed = (totals, declarerTeam) =>
    totals[1 - declarerTeam] <= SUN_DOUBLE_LIMIT && totals[declarerTeam] > SUN_DOUBLE_LIMIT;

  function playOut(hands, leader, mode, trump, locked) {
    const copy = {};
    for (const p of [0, 1, 2, 3]) copy[p] = hands[p].slice();
    const points = [0, 0];
    for (let trick = 0; trick < 8; trick++) {
      const table = [];
      for (let i = 0; i < 4; i++) {
        const pid = (leader + i) % 4;
        const card = greedyCard(pid, copy[pid], table, mode, trump, locked);
        copy[pid].splice(copy[pid].indexOf(card), 1);
        table.push([pid, card]);
      }
      leader = trickWinner(table, mode, trump);
      points[teamOf(leader)] += trickPoints(table, mode, trump) + (trick === 7 ? LAST_TRICK_BONUS : 0);
    }
    return points;
  }

  class EscalationAdvisor {
    constructor(samples, margin, rng, attemptsPerSample) {
      this.samples = samples || 24;
      this.margin = margin === undefined ? 4.0 : margin;
      this.rng = rng || Math.random;
      this.attemptsPerSample = attemptsPerSample || 12;
    }

    _plausible(deal, view) {
      if (view.buyer !== view.pid) {
        const buyerHand = deal[view.buyer];
        if (view.mode === HOKOM) {
          if (hokomStrength(buyerHand, view.trump) < HOKOM_THRESHOLD) return false;
        } else {
          const needed = view.taker === view.buyer ? SUN_THRESHOLD : SUN_THRESHOLD - ASHKAL_MAX_GAIN;
          if (sunStrength(buyerHand) < needed) return false;
        }
      }
      if (view.mode === HOKOM && view.doubler !== null && view.doubler !== view.pid
          && hokomStrength(deal[view.doubler], view.trump) < DOUBLER_MODEL_STRENGTH) return false;
      return true;
    }

    _deals(view) {
      const kb = new KnowledgeBase(view.pid);
      if (view.taker !== view.pid) kb.known[view.taker].add(view.groundCard);
      const sampler = new DealSampler(kb, view.hand, this.rng);
      const deals = [], fallback = [];
      for (let i = 0; i < this.samples * this.attemptsPerSample && deals.length < this.samples; i++) {
        const deal = sampler.sample();
        if (!deal) break;
        (this._plausible(deal, view) ? deals : fallback).push(deal);
      }
      return deals.concat(fallback.slice(0, Math.max(0, this.samples - deals.length)));
    }

    evaluate(view) {
      const effects = { [PASS]: [view.level, view.locked] };
      for (const o of view.options) if (CALL_EFFECT[o]) effects[o] = CALL_EFFECT[o];
      const locks = new Set(Object.values(effects).map(([, lock]) => lock));
      const me = teamOf(view.pid);
      const declarerTeam = teamOf(view.buyer);
      const leader = (view.dealer + 1) % 4;
      const totals = {};
      for (const o of Object.keys(effects)) totals[o] = 0;

      const deals = this._deals(view);
      for (const deal of deals) {
        const projectsByPid = {};
        for (const p of [0, 1, 2, 3]) projectsByPid[p] = detectProjects(deal[p], view.mode, view.trump);
        const decl = resolveDeclarations(projectsByPid, view.mode);
        const points = {};
        for (const lock of locks) points[lock] = playOut(deal, leader, view.mode, view.trump, lock);
        for (const [option, [level, lock]] of Object.entries(effects)) {
          const hs = scoreHand(view.mode, declarerTeam, points[lock], decl.projectPoints, decl.balootPoints, level);
          let value;
          if (hs.qahwa) {
            value = hs.winner === me ? view.target - view.totals[me] : -(view.target - view.totals[1 - me]);
          } else value = hs.final[me] - hs.final[1 - me];
          totals[option] += value;
        }
      }
      const n = Math.max(1, deals.length);
      const out = {};
      for (const [o, v] of Object.entries(totals)) out[o] = v / n;
      return out;
    }

    decide(view) {
      if (view.options.length <= 1) return PASS;
      const values = this.evaluate(view);
      let best = PASS;
      for (const [o, v] of Object.entries(values)) if (v > values[best]) best = o;
      if (best !== PASS && values[best] - values[PASS] >= this.margin) return best;
      return PASS;
    }
  }

  // ----------------------------------------------------------------- agent
  class BalootAgent {
    constructor(pid, options) {
      options = options || {};
      this.pid = pid;
      this.samples = options.samples || 12;
      this.timeBudget = options.timeBudget === undefined ? 0.6 : options.timeBudget;
      this.rng = options.rng || Math.random;
      this.kb = new KnowledgeBase(pid);
      this.advisor = new EscalationAdvisor(options.escalationSamples || 16, 4.0, this.rng);
    }

    newRound() { this.kb.reset(); }
    observeContract(mode, trump, locked, taker, groundCard) {
      this.kb.observeContract(mode, trump, locked, taker, groundCard);
    }
    observePlay(pid, card, tableBefore, mode, trump) {
      this.kb.observePlay(pid, card, tableBefore, mode, trump);
    }
    observeDeclaration(pid, cards) { this.kb.observeDeclaration(pid, cards); }

    chooseBid(hand, groundCard, bidRound, options) {
      return decideBid(hand, groundCard, bidRound, options);
    }

    chooseEscalation(view) { return this.advisor.decide(view); }

    /** PIMC: sample deals, solve each with alpha-beta, average the values.
     *  ``onStep`` lets the caller yield to the browser between samples. */
    chooseCard(view, onStep) {
      const legal = legalMoves(view.hand, view.table, view.mode, view.trump, view.locked);
      if (legal.length === 1) return Promise.resolve(legal[0]);

      const sampler = new DealSampler(this.kb.snapshot(), view.hand, this.rng);
      const cardsLeft = view.hand.length;
      const horizon = cardsLeft <= HORIZON_FULL ? cardsLeft : HORIZON;
      const search = new TrickSearch(view.pid, view.mode, view.trump, horizon, view.locked);
      const totals = new Map(legal.map((c) => [c, 0]));
      const deadline = Date.now() + this.timeBudget * 1000;
      let done = 0;
      const self = this;

      function step(resolve) {
        while (done < self.samples && (done < 3 || Date.now() < deadline)) {
          const deal = sampler.sample();
          if (!deal) break;
          for (const [card, value] of search.moveValues(deal, view.table, legal)) {
            totals.set(card, totals.get(card) + value);
          }
          done += 1;
          if (onStep && done % 2 === 0) { onStep(step.bind(null, resolve)); return; }
        }
        if (!done) {
          resolve(legal.reduce((a, b) =>
            (cheapness(b, view.mode, view.trump) < cheapness(a, view.mode, view.trump) ? b : a)));
          return;
        }
        // Best average value; ties go to the cheaper card.
        let best = legal[0];
        for (const card of legal) {
          const diff = totals.get(card) / done - totals.get(best) / done;
          if (diff > 1e-9 || (Math.abs(diff) <= 1e-9
              && cheapness(card, view.mode, view.trump) < cheapness(best, view.mode, view.trump))) {
            best = card;
          }
        }
        resolve(best);
      }
      return new Promise((resolve) => step(resolve));
    }
  }

  // ---------------------------------------------------------------- engine
  const TARGET_SCORE = 152;
  const Phase = {
    BIDDING: "BIDDING", DOUBLING: "DOUBLING", PLAYING: "PLAYING",
    TRICK_COMPLETE: "TRICK_COMPLETE", ROUND_OVER: "ROUND_OVER", MATCH_OVER: "MATCH_OVER",
  };

  class IllegalAction extends Error {}

  class GameEngine {
    constructor(observers, rng, options) {
      options = options || {};
      this.observers = observers || [];
      this.rng = rng || Math.random;
      this.ashkalRequiresHokom = !!options.ashkalRequiresHokom;
      this.totals = [0, 0];
      this.history = [];
      this.dealer = Math.floor(this.rng() * 4);
      this.phase = Phase.ROUND_OVER;
      this.hands = { 0: [], 1: [], 2: [], 3: [] };
      this.table = [];
      this.mode = null; this.trump = null; this.buyer = null; this.taker = null;
      this.ashkal = false;
      this.level = NORMAL; this.locked = false; this.doubler = null;
      this._qahwaWinner = null;
      this._bidQueue = []; this._escalationQueue = [];
    }

    _notify(method, ...args) {
      for (const obs of this.observers) if (typeof obs[method] === "function") obs[method](...args);
    }

    startRound(deck) {
      if (this.phase === Phase.MATCH_OVER) throw new IllegalAction("Match is over");
      this.dealer = (this.dealer + 1) % 4;
      deck = deck || shuffled(fullDeck(), this.rng);
      this.hands = {};
      for (let p = 0; p < 4; p++) this.hands[p] = deck.slice(p * 5, p * 5 + 5);
      this.publicCard = deck[20];
      this._stock = deck.slice(21);

      this.bidStarter = (this.dealer + 1) % 4;
      this.bidOrder = [1, 2, 3, 4].map((i) => (this.dealer + i) % 4);
      this.bidRound = 1;
      this._bidQueue = this.bidOrder.slice();
      this.hokomBid = null;
      this.bidLog = [];

      this.mode = null; this.trump = null; this.buyer = null; this.taker = null;
      this.ashkal = false;
      this.level = NORMAL; this.locked = false; this.doubler = null;
      this._escalationQueue = [];
      this.escalationLog = [];
      this.table = [];
      this.turn = this.bidStarter;
      this.tricksPlayed = 0;
      this.cardPoints = [0, 0];
      this.projects = {};
      this.declarations = null;
      this.phase = Phase.BIDDING;
      this._notify("newRound");
    }

    get currentBidder() {
      return this.phase === Phase.BIDDING && this._bidQueue.length ? this._bidQueue[0] : null;
    }

    ashkalEligible(pid) {
      if (pid !== this.dealer && pid !== (this.dealer + 3) % 4) return false;
      if (this.ashkalRequiresHokom) {
        return this.hokomBid !== null && teamOf(this.hokomBid[0]) !== teamOf(pid);
      }
      return true;
    }

    bidOptions() {
      const pid = this.currentBidder;
      if (pid === null) return [];
      const options = [PASS, BUY_SUN];
      if (this.hokomBid === null) options.push(this.bidRound === 1 ? BUY_HOKOM : BUY_HOKOM_THANI);
      if (this.ashkalEligible(pid)) options.push(BUY_ASHKAL);
      return options;
    }

    thaniSuits() { return SUITS.filter((s) => s !== suitOf(this.publicCard)); }

    applyBid(pid, action, trump) {
      if (this.phase !== Phase.BIDDING || pid !== this.currentBidder) {
        throw new IllegalAction(`Player ${pid} cannot bid now`);
      }
      if (!this.bidOptions().includes(action)) {
        throw new IllegalAction(`${action} is not available to player ${pid} now`);
      }
      if (action === BUY_HOKOM_THANI && !this.thaniSuits().includes(trump)) {
        throw new IllegalAction("Hokom thani needs a suit other than the ground card's");
      }
      if (action === BUY_HOKOM) trump = suitOf(this.publicCard);
      if (action === PASS || action === BUY_SUN || action === BUY_ASHKAL) trump = null;
      this.bidLog.push([this.bidRound, pid, action, trump]);

      if (action === BUY_SUN || action === BUY_ASHKAL) {
        this._finishBidding(pid, SUN, null, action === BUY_ASHKAL);
        return "bought";
      }
      this._bidQueue.shift();
      if (action === BUY_HOKOM || action === BUY_HOKOM_THANI) {
        this.hokomBid = [pid, trump];
        if (this.bidRound === 1) this._bidQueue = this.bidOrder.filter((p) => p !== pid);
        if (!this._bidQueue.length) { this._finishBidding(pid, HOKOM, trump, false); return "bought"; }
        return "hokom";
      }
      if (this._bidQueue.length) return "pass";
      if (this.hokomBid !== null) {
        this._finishBidding(this.hokomBid[0], HOKOM, this.hokomBid[1], false);
        return "bought";
      }
      if (this.bidRound === 1) {
        this.bidRound = 2;
        this._bidQueue = this.bidOrder.slice();
        return "second_round";
      }
      this.phase = Phase.ROUND_OVER;
      return "redeal";
    }

    _finishBidding(buyer, mode, trump, ashkal) {
      this.mode = mode; this.trump = trump; this.buyer = buyer; this.ashkal = ashkal;
      this.taker = ashkal ? partnerOf(buyer) : buyer;
      this._bidQueue = [];
      this._completeDeal();
    }

    _completeDeal() {
      this.hands[this.taker].push(this.publicCard);
      let stock = this._stock.slice();
      for (let offset = 0; offset < 4; offset++) {
        const p = (this.bidStarter + offset) % 4;
        const need = 8 - this.hands[p].length;
        this.hands[p] = this.hands[p].concat(stock.slice(0, need));
        stock = stock.slice(need);
      }
      this.projects = {};
      for (let p = 0; p < 4; p++) this.projects[p] = detectProjects(this.hands[p], this.mode, this.trump);
      this.declarations = resolveDeclarations(this.projects, this.mode);
      this.turn = this.bidStarter;

      const defenders = this.bidOrder.filter((p) => teamOf(p) !== teamOf(this.buyer));
      if (this.mode === HOKOM || sunDoubleAllowed(this.totals, teamOf(this.buyer))) {
        this._escalationQueue = defenders;
        this.phase = Phase.DOUBLING;
      } else this._beginPlay();
    }

    get escalationTurn() {
      if (this.phase !== Phase.DOUBLING || !this._escalationQueue.length) return null;
      return this._escalationQueue[0];
    }

    escalationOptions() {
      if (this.escalationTurn === null) return [];
      if (this.level === NORMAL) {
        return this.mode === HOKOM ? [PASS, CALL_DOUBLE, CALL_DOUBLE_CLOSED] : [PASS, CALL_DOUBLE];
      }
      if (this.level === DOUBLE) return [PASS, CALL_THREE];
      if (this.level === THREE) return [PASS, CALL_FOUR, CALL_FOUR_CLOSED];
      if (this.level === FOUR) return [PASS, CALL_QAHWA];
      return [];
    }

    escalationView(pid) {
      return {
        pid, hand: this.hands[pid].slice(), mode: this.mode, trump: this.trump,
        buyer: this.buyer, taker: this.taker, groundCard: this.publicCard, dealer: this.dealer,
        level: this.level, locked: this.locked, doubler: this.doubler,
        options: this.escalationOptions(), totals: this.totals.slice(), target: TARGET_SCORE,
      };
    }

    applyEscalation(pid, action) {
      if (pid !== this.escalationTurn) throw new IllegalAction(`Player ${pid} cannot raise now`);
      if (!this.escalationOptions().includes(action)) throw new IllegalAction(`${action} is not available now`);
      this.escalationLog.push([pid, action]);
      this._escalationQueue.shift();

      if (action === PASS) {
        if (this.level === NORMAL && this._escalationQueue.length) return "pass";
        this._escalationQueue = [];
        this._beginPlay();
        return "done";
      }
      [this.level, this.locked] = CALL_EFFECT[action];
      if (this.level === DOUBLE) this.doubler = pid;
      if (this.mode === SUN || this.level === QAHWA) {
        this._escalationQueue = [];
        this._beginPlay();
        return "done";
      }
      this._escalationQueue = [this.level === DOUBLE || this.level === FOUR ? this.buyer : this.doubler];
      return "raised";
    }

    _beginPlay() {
      this.phase = Phase.PLAYING;
      this.turn = this.bidStarter;
      this._notify("observeContract", this.mode, this.trump, this.locked, this.taker, this.publicCard);
    }

    viewFor(pid) {
      return {
        pid, hand: this.hands[pid].slice(), table: this.table.slice(),
        mode: this.mode, trump: this.trump, locked: this.locked,
      };
    }

    legalMoves(pid) {
      if (this.phase !== Phase.PLAYING || pid !== this.turn) return [];
      return legalMoves(this.hands[pid], this.table, this.mode, this.trump, this.locked);
    }

    currentWinner() {
      return this.table.length ? trickWinner(this.table, this.mode, this.trump) : null;
    }

    play(pid, card) {
      if (!this.legalMoves(pid).includes(card)) {
        throw new IllegalAction(`Player ${pid} cannot play ${card} now`);
      }
      const tableBefore = this.table.slice();
      this.hands[pid].splice(this.hands[pid].indexOf(card), 1);
      this.table.push([pid, card]);
      this._notify("observePlay", pid, card, tableBefore, this.mode, this.trump);
      if (this.table.length === 4) this.phase = Phase.TRICK_COMPLETE;
      else this.turn = (this.turn + 1) % 4;
    }

    resolveTrick() {
      if (this.phase !== Phase.TRICK_COMPLETE) throw new IllegalAction("Trick is not complete");
      const winner = trickWinner(this.table, this.mode, this.trump);
      let points = trickPoints(this.table, this.mode, this.trump);
      this.tricksPlayed += 1;
      if (this.tricksPlayed === 8) points += LAST_TRICK_BONUS;
      this.cardPoints[teamOf(winner)] += points;
      this.table = [];
      this.turn = winner;
      const result = { winner, points, trickNumber: this.tricksPlayed, declarations: null, roundResult: null };

      if (this.tricksPlayed === 1) {
        for (const [pid, projs] of Object.entries(this.declarations.shown)) {
          for (const p of projs) this._notify("observeDeclaration", Number(pid), p.cards);
        }
        result.declarations = this.declarations;
      }
      if (this.tricksPlayed === 8) result.roundResult = this._scoreRound();
      else this.phase = Phase.PLAYING;
      return result;
    }

    _scoreRound() {
      const decl = this.declarations;
      const hs = scoreHand(this.mode, teamOf(this.buyer), this.cardPoints,
                           decl.projectPoints, decl.balootPoints, this.level);
      let final = hs.final.slice();
      if (hs.qahwa) {
        const w = hs.winner;
        final = [0, 0];
        final[w] = Math.max(TARGET_SCORE, this.totals[1 - w] + 1) - this.totals[w];
        this._qahwaWinner = w;
      }
      for (const t of [0, 1]) this.totals[t] += final[t];
      const result = {
        mode: this.mode, trump: this.trump, buyer: this.buyer, cardPoints: this.cardPoints.slice(),
        base: hs.gamePoints.slice(), projectPoints: decl.teamPoints.slice(),
        balootPoints: decl.balootPoints.slice(), final, buyerFailed: !hs.declarerWon,
        totalsAfter: this.totals.slice(), level: this.level, locked: this.locked,
        doubler: this.doubler, ashkal: this.ashkal, winner: hs.winner, qahwa: hs.qahwa,
      };
      this.history.push(result);
      if (hs.qahwa || (Math.max(...this.totals) >= TARGET_SCORE && this.totals[0] !== this.totals[1])) {
        this.phase = Phase.MATCH_OVER;
      } else this.phase = Phase.ROUND_OVER;
      return result;
    }

    get matchWinner() {
      if (this.phase !== Phase.MATCH_OVER) return null;
      if (this._qahwaWinner !== null) return this._qahwaWinner;
      return this.totals[0] > this.totals[1] ? 0 : 1;
    }

    newMatch() {
      this.totals = [0, 0];
      this.history = [];
      this._qahwaWinner = null;
      this.phase = Phase.ROUND_OVER;
    }
  }

  return {
    SUITS, SUIT_NAMES, SUIT_SYMBOLS, RANKS, TRUMP_ORDER, PLAIN_ORDER,
    PLAIN_POINTS, TRUMP_POINTS, LAST_TRICK_BONUS, HOKOM, SUN,
    rankOf, suitOf, isRed, makeCard, fullDeck, shuffled, mulberry32, choice, sortHand,
    teamOf, partnerOf, isTrump, trumpStrength, plainStrength, cardPoints, trickPoints,
    beats, trickWinner, highestTrumpOnTable, legalMoves,
    detectProjects, resolveDeclarations, projectPoints,
    NORMAL, DOUBLE, THREE, FOUR, QAHWA, LEVEL_NAMES, LEVEL_NAMES_AR,
    baseTotal, convertCountingPoints, countingTeam, raisingTeam, scoreHand,
    KnowledgeBase, DealSampler, TrickSearch, cheapness, greedyCard,
    PASS, BUY_SUN, BUY_HOKOM, BUY_HOKOM_THANI, BUY_ASHKAL,
    hokomStrength, sunStrength, bestThaniSuit, decideBid,
    CALL_DOUBLE, CALL_DOUBLE_CLOSED, CALL_THREE, CALL_FOUR, CALL_FOUR_CLOSED, CALL_QAHWA,
    CALL_EFFECT, sunDoubleAllowed, playOut, EscalationAdvisor,
    BalootAgent, GameEngine, Phase, IllegalAction, TARGET_SCORE,
  };
});
